"OLAYLAR_EK2:1858-06-06:0":{"b": ["მიწის კანუნნამე", "6bae243a"], "d": ["მიწის სამართლის მოდერნიზაციის კანუნნამემ სახელმწიფო (მირი) მიწებზე ფაქტობრივი სარგებლობა რეგისტრაციის საბუთს დაუკავშირა; ის დღევანდელი ახლო აღმოსავლეთის საკუთრების წყობის ერთ-ერთი ძირითადი დოკუმენტია.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["პირველი ლექციები დარულფუნუნში", "08f74066"], "d": ["უნივერსიტეტის დონის განათლების მისაცემად შექმნილმა დარულფუნუნმა საჯარო ლექციებით დაიწყო მუშაობა; წყვეტილად არსებული დაწესებულება 1900 წელს საბოლოოდ გაიხსნა და სტამბოლის უნივერსიტეტის ბირთვი გახდა.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["ვილაიეთების დებულება", "ad20853b"], "d": ["ეიალეთების წყობის ნაცვლად ფრანგული ნიმუშის ვილაიეთური ორგანიზაცია დაარსდა; მიდჰათ-ფაშას დუნაის ვილაიეთის პრაქტიკა ნიმუშად აიღეს და მთელ ქვეყანაში გაავრცელეს.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["აბდულაზიზის ევროპული მოგზაურობა", "9ff0fa1e"], "d": ["ოსმალო ფადიშაჰის პირველი მშვიდობიანი მიზნის ევროპული მოგზაურობა; პარიზის გამოფენისა და ლონდონის ვიზიტებმა დიპლომატიისა და მოდერნიზაციის ვიტრინის ფუნქცია შეასრულა.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["გალათასარაის სასულთნო სკოლა გაიხსნა", "f9688524"], "d": ["ფრანგულენოვანი ლიცეუმი, რელიგიისა და ეროვნების განურჩევლად მოსწავლეთა შემადგენლობით, თანზიმათის განათლებაში თანასწორობის იდეალის სიმბოლო გახდა.", "c9d5821d"]}
